{"command":"cd /workspace && sha256sum requirements.contract.json counter.model.json && echo "--- requirements unchanged check ---" && python3 - <<'EOF'
import json
m=json.load(open('counter.model.json'))
def ev(t,s,a):
    op=t["op"]
    if op=="constant": return t["value"]%16
    if op=="state": return s[t["field"]]
    if op=="parameter": return a[t["name"]]
    if op=="add": return (ev(t["left"],s,a)+ev(t["right"],s,a))%16
    if op=="sub": return (ev(t["left"],s,a)-ev(t["right"],s,a))%16
    if op=="if": return ev(t["then"],s,a) if ev(t["condition"],s,a) else ev(t["else"],s,a)
    raise ValueError(op)
def cond(c,s,a,out):
    op=c["op"]
    if op=="true": return True
    if op=="false": return False
    if op=="equal": return ev(c["left"],s,a)==ev(c["right"],s,a)
    if op=="less": return ev(c["left"],s,a)<ev(c["right"],s,a)
    if op=="less_equal": return ev(c["left"],s,a)<=ev(c["right"],s,a)
    if op=="not": return not cond(c["argument"],s,a,out)
    if op=="and": return cond(c["left"],s,a,out) and cond(c["right"],s,a,out)
    if op=="or": return cond(c["left"],s,a,out) or cond(c["right"],s,a,out)
    raise ValueError(op)
req=json.load(open('requirements.contract.json'))
def evout(w,s,a):
    if w["op"]=="output": return out[w["field"]]
    return ev(w,s,a)
out={}
bad=[];n=0
for v in range(16):
    for amt in range(16):
        n+=1
        s={"value":v}; a={"amount":amt}
        out={"value":ev(m["transition"]["value"],s,a)}
        for p in req["properties"]:
            l=evout(p["statement"]["left"],s,a); r=evout(p["statement"]["right"],s,a)
            if not cond(p["statement"],s,a,out):
                bad.append((v,amt,p["name"],out))
        # spec check: value+amount when fits in 0..15 else value
        exp = v+amt if v+amt<=15 else v
        if out["value"]!=exp: bad.append((v,amt,"spec",out,exp))
print("assignments checked:",n)
print("violations:",len(bad), bad[:5])
EOF"}

