def ev(t,s,a,out):
    op=t["op"]
    if op=="constant": return t["value"]%16
    if op=="state": return s[t["field"]]
    if op=="parameter": return a[t["name"]]
    if op=="output": return out[t["field"]]
    if op=="add": return (ev(t["left"],s,a,out)+ev(t["right"],s,a,out))%16
    if op=="sub": return (ev(t["left"],s,a,out)-ev(t["right"],s,a,out))%16
    if op=="if": return ev(t["then"],s,a,out) if cond(t["condition"],s,a,out) else ev(t["else"],s,a,out)
    raise ValueError(op)
def cond(c,s,a,out):
    op=c["op"]
    if op=="true": return True
    if op=="false": return False
    if op=="equal": return ev(c["left"],s,a,out)==ev(c["right"],s,a,out)
    if op=="less": return ev(c["left"],s,a,out)<ev(c["right"],s,a,out)
    if op=="less_equal": return ev(c["left"],s,a,out)<=ev(c["right"],s,a,out)
    if op=="not": return not cond(c["argument"],s,a,out)
    if op=="and": return cond(c["left"],s,a,out) and cond(c["right"],s,a,out)
    if op=="or": return cond(c["left"],s,a,out) or cond(c["right"],s,a,out)
    raise ValueError(op)
bad=[];n=0
for v in range(16):
    for amt in range(16):
        n+=1
