            if not cond(p["statement"],s,a,out):
                bad.append((v,amt,p["name"],out))
        exp = v+amt if v+amt<=15 else v
        if out["value"]!=exp: bad.append((v,amt,"spec",out["value"],exp))
print("assignments checked:",n,"| violations:",len(bad),bad[:5])
